use std::path::Path;
use sysmlv2_model::{model::{Model, GraphFormat}, json::{Derived, ResolvedModel}};
fn library(model: &mut Model, path: &Path) {
    let mut entries: Vec<_> = std::fs::read_dir(path).unwrap().map(|e| e.unwrap().path()).collect();
    entries.sort();
    for entry in entries {
        if entry.is_dir() { library(model, &entry); }
        else if matches!(entry.extension().and_then(|x|x.to_str()), Some("sysml"|"kerml")) {
            model.add_library_source(entry.to_string_lossy(), &std::fs::read_to_string(&entry).unwrap());
        }
    }
}
fn main() {
 std::thread::Builder::new().stack_size(16*1024*1024).spawn(|| {
    let mut model = Model::with_graph_format(GraphFormat::CanonicalV3);
    library(&mut model, Path::new("vendor/sysml-library/sources"));
    model.add_source("accept-triggers.sysml", &std::fs::read_to_string("tests/conformance/fixtures/accept-triggers.sysml").unwrap());
    assert!(model.unit(0).diagnostics.is_empty());
    let mut graph = ResolvedModel::build(&model);
    let package = graph.resolve_qualified("AcceptTriggers").unwrap();
    graph.implied_relationships(package);
    for name in ["absolute", "relative", "conditional"] {
        let accept = graph.resolve_qualified(&format!("AcceptTriggers::Reception::{name}")).unwrap();
        let Derived::Value(value) = graph.derived(accept,"payloadArgument") else { panic!("missing payload"); };
        let trigger = value.element().unwrap();
        assert_eq!(graph.element_type(trigger),"TriggerInvocationExpression");
        let Derived::Value(value) = graph.derived(trigger,"parameter") else { panic!("missing parameters"); };
        let count = value.elements().len();
        let Derived::Value(value) = graph.derived(accept,"ownedFeature") else { panic!("missing owned features"); };
        let connectors = value.elements().into_iter().filter(|&e|sysmlv2_model::json::metaclass_conforms(graph.element_type(e),"BindingConnector")).count();
        println!("{name}: trigger parameters={count}, accept-owned BindingConnectors={connectors}");
    }
 }).unwrap().join().unwrap();
}
